window.FIXTURES=window.FIXTURES||{};window.FIXTURES["speech"]={"vid":"ox5RUYZ-U-U","speaker":"Balendra Shah","role":"Prime Minister","country":"Nepal","region":"Asia-Pacific","url":"https://www.youtube.com/watch?v=ox5RUYZ-U-U","date":"20260925","title":"🇳🇵 Nepal - Prime Minister Addresses United Nations General Assembly 81st Session | #UNGA","seconds":755,"words":1740,"counts":{"claims":26,"promises":7,"attacks":0},"topics":[{"topic":"Nepal climate","share":0.3361,"seconds":254},{"topic":"Climate finance","share":0.0897,"seconds":68},{"topic":"Climate justice","share":0.0883,"seconds":67},{"topic":"Global supply chain","share":0.086,"seconds":65},{"topic":"Nepal disaster","share":0.0852,"seconds":64},{"topic":"Himalayan climate","share":0.0848,"seconds":64},{"topic":"Nepal economy","share":0.0816,"seconds":62},{"topic":"Nepal floods","share":0.0804,"seconds":61},{"topic":"Climate resilience","share":0.068,"seconds":51}],"timeline":[[10,73,null],[75,135,"Nepal floods"],[136,202,"Nepal climate"],[203,267,"Nepal disaster"],[268,330,"Nepal climate"],[332,396,"Himalayan climate"],[397,462,"Nepal climate"],[462,530,"Climate finance"],[531,593,"Nepal economy"],[594,659,"Global supply chain"],[660,727,"Climate justice"],[728,789,"Nepal climate"],[790,841,"Climate resilience"]],"stances":{"Nepal floods":"Balendra Shah states that the catastrophic floods in Nepal were a warning to the world regarding climate disaster that was not heeded sufficiently.","Nepal climate":"Balendra Shah states that political leaders have been negligent in translating scientific warnings into action and highlights the cross-border devastation caused by climate change.","Nepal disaster":"Balendra Shah expresses gratitude for international assistance while highlighting Nepal's minimal contribution to global emissions despite suffering severe consequences from the disaster.","Himalayan climate":"Balendra Shah argues that nations with greater historical contribution and capacity must take more action on climate justice, proposes a regional mechanism led by Nepal, India, and China to manage glacial risks, and emphasizes the Himalayas' critical role in global life support systems.","Climate finance":"Balendra Shah argues that climate finance must shift from loans to grants and avoid bureaucratic delays to address loss and damage effectively.","Nepal economy":"Balendra Shah argues that Nepal requires a fairer global economic order and highlights specific domestic shortages caused by international adversities.","Global supply chain":"Balendra Shah argues that the global supply chain prioritizes military logistics over essential civilian needs like food and fuel, disproportionately harming developing nations.","Climate justice":"Balendra Shah argues that climate justice requires distributive and procedural fairness, ensuring small nations have a voice and that the future of vulnerable communities counts equally.","Climate resilience":"Balendra Shah calls for financing resilience, investing in insurance and innovation, building stronger infrastructure, reducing fossil fuel dependence, and reforming the global order to protect the weakest."},"claims":[{"t":96,"quote":"Four weeks ago, the world saw shocking images of catastrophic floods that swept away Nepal's mountain communities with ferocity.","topic":"Nepal floods","kind":"fact"},{"t":108,"quote":"The Bhosi Triculi disaster was not just a local tragedy. It was a warning to the world.","topic":"Nepal floods","kind":"fact"},{"t":119,"quote":"Nearly three years ago, standing in the shadow of our Mount Everest, the Secretary General of United Nations warned humanity about the madness and impending climate disaster.","topic":"Nepal floods","kind":"fact"},{"t":151,"quote":"Last month we saw the tragic consequences. A warming climate that that is destabilizing the fragile Himalayan ecology, melting perafrost that are fracturing mountains, slopes beneath the glaciers and accelerating the risk of ice, rock avalance, floods, landslides and other cascading hazards.","topic":"Nepal climate","kind":"fact"},{"t":171,"quote":"The resulting devastated The resulting devastation unleashed havoc on both sides of Nepal Sina border. The flood continued downstream to the India.","topic":"Nepal climate","kind":"fact"},{"t":232,"quote":"at least 1400 death and over 66 6,000 people still missing","topic":"Nepal disaster","kind":"number"},{"t":239,"quote":"physical recovery needs at about 10% of GDP","topic":"Nepal disaster","kind":"number"},{"t":255,"quote":"Nepal contributes less than 0.1% of global greenhouse gas emission","topic":"Nepal disaster","kind":"number"},{"t":268,"quote":"Our glaciers are retreating. Our mountain slopes are be becoming unstable. Our rivers are becoming less predictable.","topic":"Nepal climate","kind":"fact"},{"t":286,"quote":"It destroys roads, bridges, schools, homes, farms and livelihoods.","topic":"Nepal climate","kind":"fact"},{"t":295,"quote":"And and it forces a poor country to borrow money to repair damage it did not cause.","topic":"Nepal climate","kind":"fact"},{"t":350,"quote":"The Hindukush Himalay is home to nearly two billion people.","topic":"Himalayan climate","kind":"number"},{"t":354,"quote":"These mountains provide water, ecosystem, agriculture and livelihood to population far beyond Nepal.","topic":"Himalayan climate","kind":"fact"},{"t":411,"quote":"We have restored forest cover nearly half of our territory.","topic":"Nepal climate","kind":"number"},{"t":415,"quote":"We are installing hydropower at a pace enough to power all clean energy needs and displace dirty sources abroad.","topic":"Nepal climate","kind":"fact"},{"t":422,"quote":"We are promoting electric mobility with an adoption rate to match parts of Europe.","topic":"Nepal climate","kind":"fact"},{"t":483,"quote":"The loss and damage fund, the global environment facility and other financing mechanism remain grossly inadequate.","topic":"Climate finance","kind":"fact"},{"t":543,"quote":"In 1994, UNDP's human development report conceptualized the notion of human insecurity.","topic":"Nepal economy","kind":"fact"},{"t":561,"quote":"The new majority government in Nepal elected through the fairest and most peaceful elections in our history this March","topic":"Nepal economy","kind":"self_credit"},{"t":600,"quote":"Intercontinental missiles arrive on time. Rifles and aminations cross border, clear every bottleneck, meet each deadline.","topic":"Global supply chain","kind":"fact"},{"t":607,"quote":"But a pan in Nepal cannot procure his fertilizer or fuel at market price at a time of need.","topic":"Global supply chain","kind":"fact"},{"t":626,"quote":"We have built a world with flawless logistics for war and broken logistics for food.","topic":"Global supply chain","kind":"fact"},{"t":661,"quote":"I'm told I'm the youngest head of government to address this assembly this year.","topic":"Climate justice","kind":"self_credit"},{"t":683,"quote":"a world that is and and a world that can deliver a weapon anywhere in 72 hours has no excuse for leaving a farmer without means of decent livelihood.","topic":"Climate justice","kind":"fact"},{"t":772,"quote":"The Nepal floods signal a future The Nepal flood signals a future saved by rising climate extremes.","topic":"Nepal climate","kind":"fact"},{"t":790,"quote":"Let us finance resilience and invest in insurance and innovation. Let us build stronger infrastructure and institutions. Let us reduce fossil fuel dependence. Let us build system that warn, alert and save lives.","topic":"Climate resilience","kind":"fact"}],"promises":[{"t":369,"quote":"we propose that we establish Himalay climate resilience mechanism led by Nepal, India and China.","topic":"Himalayan climate","kind":"promise"},{"t":376,"quote":"Through this mechanism through this mechanism, let us share satellite data and expertise.","topic":"Himalayan climate","kind":"promise"},{"t":387,"quote":"Let us monitor dangerous glacial legs.","topic":"Himalayan climate","kind":"promise"},{"t":389,"quote":"Let us strengthen joint early warning systems and when disaster strikes let us coordinate assistance across borders.","topic":"Himalayan climate","kind":"promise"},{"t":747,"quote":"Our youths have demanded a politics of integrity and The generational shift is not only a national story. It is part of global awakening against conflict, inequities and lack of opportunities.","topic":"Nepal climate","kind":"promise"},{"t":762,"quote":"The commitment of my government is clear to build a state that delivers decent jobs, social protection, and a fair chance to every Nepali to thrive at home.","topic":"Nepal climate","kind":"promise"},{"t":786,"quote":"we must move from ad hoc responses to a culture of preparedness.","topic":"Nepal climate","kind":"promise"}],"attacks":[],"greece":[],"said":[],"pickup":[],"transcript":[{"t":10,"topic":null,"text":"The assembly will hear an address by his excellency Belindra Sha, Prime Minister of Nepal. I request protocol to escort his excellency and invite him to address the assembly. Mr. President, Mr. Secretary General, excellencies, distinguished delegates, ladies and gentlemen, I come before you from Nepal, a distant country in Himalayas, carrying a close warning for I wish I could stand here today simply to talk about development, democracy, peace, and the hopes of a young nation. Instead, I must speak about death and destruction of epic proportion. About families waiting for loved ones will never come home."},{"t":75,"topic":"Nepal floods","text":"About communities searching through the mud, rocks, water for the people, bodies may never be recovered. about bridges, about roads, schools, homes, livelihood swept away in minutes, about a country whose steady progress to achieve sustainable development goals has been Four weeks ago, the world saw shocking images of catastrophic floods that swept away Nepal's mountain communities with ferocity. Many have called mountain tsunami or Himalayan tsunami. The Bhosi Triculi disaster was not just a local tragedy. It was a warning to the world. And I ask you today, have we really heard that warning? Nearly three years ago, standing in the shadow of our Mount Everest, the Secretary General of United Nations warned humanity about the madness and impending climate disaster. That cry from the rooftop of the world was not heard enough loudly. We in Nepal heard it."},{"t":136,"topic":"Nepal climate","text":"Our communities heard it. Scientists around the world heard it. They reputated with evidence. But we the political leaders have been negligent to translate those warning into action at the speed and scale that the vulnerable people require. Last month we saw the tragic consequences. A warming climate that that is destabilizing the fragile Himalayan ecology, melting perafrost that are fracturing mountains, slopes beneath the glaciers and accelerating the risk of ice, rock avalance, floods, landslides and other cascading hazards. The resulting devastated The resulting devastation unleashed havoc on both sides of Nepal Sina border. The flood continued downstream to the India. This tells of us something fundamental. Climate change does not recognize borders. Glaciers and floods do not travel with stamps and passports. Excellencies, I'm not here to complain but to share some suggestions. First, I wish to express Nepal's deep gratitude to all those who came to our aid aftermath of the delus."},{"t":203,"topic":"Nepal disaster","text":"Our immediate neighbors India and China offered prompt and generous assistance. Other friendly countries, the United Nations system, humanitarian agencies, philanthropies and people around the world stood with Nepal. To all of them, I say thank you on the behalf of grateful people of Nepal now faces a massive task of recovery and reconstruction after at least 1400 death and over 66 6,000 people still missing a rapid assessment peg physical recovery needs at about 10% of GDP as in rebuilding after post disaster like 2015 Gorka earthquake we count on your solidarity and support but we must also understand why This disaster matters beyond Nepal. Nepal contributes less than 0.1% of global greenhouse gas emission. We did not create this crisis. Yet we are paying for Yet we are paying a colossal price for it."},{"t":268,"topic":"Nepal climate","text":"Our glaciers are retreating. Our mountain slopes are be becoming unstable. Our rivers are becoming less predictable. And every major disaster threatens to the to erase years of development. For Nepal, climate catastrophe is not just a humanitarian event but a development emergency. It destroys roads, bridges, schools, homes, farms and livelihoods. It destroys clean energy infrastructure that we need to fuel our future. And and it forces a poor country to borrow money to repair damage it did not cause. But we are not here to blame any country or continent. We are here we are not here to turn climate change into another geopolitical battlefield. We are here to ask everyone to recommit to shared responsibility and solid solidarity through the United Nation framework convention on climate change. The international community has already agreed to the principle of common differentiated responsibility and respective capabilities."},{"t":332,"topic":"Himalayan climate","text":"Those who have historically contributed more to the problem and those with greater capacity to respond must do more. Climate justice cannot remain a beautiful phrase in United Nations document. People of our country be allowed to build their future instead of constantly rebuilding their past. Excellencies, the Hindukush Himalay is home to nearly two billion people. These mountains provide water, ecosystem, agriculture and livelihood to population far beyond Nepal. The Himalayas are not peripheral to the planet. They are part of planet's life support system. That is why as an urgent first step, we propose that we establish Himalay climate resilience mechanism led by Nepal, India and China. Through this mechanism through this mechanism, let us share satellite data and expertise. Let us monitor dangerous glacial legs. Let us strengthen joint early warning systems and when disaster strikes let us coordinate assistance across borders."},{"t":397,"topic":"Nepal climate","text":"Let the Himalayas become laboratory of international cooperation rather than frontier of fragmented information. Remark remarkable for at least developed country. Nepal is already paying a global role exceeding its ecological share. We have restored forest cover nearly half of our territory. We are installing hydropower at a pace enough to power all clean energy needs and displace dirty sources abroad. We are promoting electric mobility with an adoption rate to match parts of Europe. We are strengthening climate adaptation at local level and we shall do more to withstand increased intensity and frequency of climate disaster. But Nepal cannot build resilience alone against the crisis made worse by the failure of global governance. This is why this is this is why this assembly must note six words relief, rehabilitation, reconstruction and also responsibility, reparation, resilience. The first three are what we need after disaster. The second three are what we need to ensure that disaster does not become a permanent condition."},{"t":462,"topic":"Climate finance","text":"When a climate-driven disaster destroys infrastructure of a poor country, the answer cannot simply be another mega loan or a patchwork of small grants. We need adequate grant-based support. We need adequate grant-based support from the world. The loss and damage fund, the global environment facility and other financing mechanism remain grossly inadequate. Climate finance must not become bureaucr another bureaucratic maze through which vulnerable countries spend years that they need help. When the house is burning, we do not ask family to complete 50 forms. We act. This is what climate justice must mean. Excellencies, this brings me to a larger question. What kind of international order do you want? The United Nation was born from humanity's experience of horrific world war. It prom its promise was the sovereignty would matter, international law would matter, the dignity of every human being would matter and the weak would not simply have to accept whatever the powerful decide."},{"t":531,"topic":"Nepal economy","text":"Today that international system is under strain. Too often military and economic power determines whose whose voice is heard. Nepal believes we need much fairer global economic order. In 1994, UNDP's human development report conceptualized the notion of human insecurity. It equated security with people rather than territories and with development rather than arms. It called for the peace dividend to secure freedoms from fear and want. The new majority government in Nepal elected through the fairest and most peaceful elections in our history this March has had to weather many international adver adversities since when a poor farmer in Nepal went to sew her seeds in monsoon fertilizers didn't reach her on time when we wanted to pave a new highway there was no bitamine when a family sat down for an evening meal there was shortage of cooking gas on the on the one hand there are melting glaciers and failing harvest to floods arriving without warning."},{"t":594,"topic":"Global supply chain","text":"On the other hand, a global supply chain punishes poor people for causes beyond reason. Intercontinental missiles arrive on time. Rifles and aminations cross border, clear every bottleneck, meet each deadline. But a pan in Nepal cannot procure his fertilizer or fuel at market price at a time of need. We have built a world with flawless We have built a world with flawless logistics for war and broken logistics for food. And this is not Nepal's private misfortune. Ask Bangladesh, ask Bhutan, ask India, ask the Maldives, ask Pakistan, ask Sri Lanka, ask any other country in our region and you'll hear the same account. Hit by the climate we did not warm and again hit by the wars we did not start. This tells us there is a lot more broken than meets the eye in the global cooperation."},{"t":660,"topic":"Climate justice","text":"Excellencies, I'm told I'm the youngest head of government to address this assembly this year. I did not come here to make that a story. I came to make sure what whatever else is said from this podium, one thing is said plainly. A country that is willing to pay should be able to buy. And a world that is and and a world that can deliver a weapon anywhere in 72 hours has no excuse for leaving a farmer without means of decent livelihood. This is why we believe in multilateralism. This is why we need United Nations in which presence of small poor country is felt and we can work together towards outcomes. Climate justice is therefore not only about money. It is about distributive justice who bears the cost. It is about procedural justice who has a voice. It is about it is about whether future of mountain communities, small island states, landlock and least developed countries and generation yet unborn count equally."},{"t":728,"topic":"Nepal climate","text":"Starting tomorrow at the Sagar Mata to seaside event right here at United Nations, Nepal is ready to help lead this conversation. Mr. President and excellencies, we are at this general assembly at a moment of profound global uncertainty and with a rene renewed democratic mandate that reflects the aspiration of new generation. Our youths have demanded a politics of integrity and The generational shift is not only a national story. It is part of global awakening against conflict, inequities and lack of opportunities. The commitment of my government is clear to build a state that delivers decent jobs, social protection, and a fair chance to every Nepali to thrive at home. The Nepal floods signal a future The Nepal flood signals a future saved by rising climate extremes. Our baselines are no longer re relevant and we must move from ad hoc responses to a culture of preparedness."},{"t":790,"topic":"Climate resilience","text":"Let us finance resilience and invest in insurance and innovation. Let us build stronger infrastructure and institutions. Let us reduce fossil fuel dependence. Let us build system that warn, alert and save lives. Let us reform the order that leaves the weakest with least power. And when the next warning comes from the rooftop of the world, let us be ready to hear it and ready to act. You sure? On behalf of the assembly, I wish to thank the prime minister of Nepal."}],"compare":[{"topic":"Climate Change","share":0.3308,"mean":0.0413,"rank":2,"others":77},{"topic":"Global Trade","share":0.086,"mean":0.0043,"rank":4,"others":7}]};
